class AjaxUpdateStatusVincView(View):
    """Base Async View."""

    @classonlymethod
    def as_view(cls, **initkwargs):
        view = super().as_view(**initkwargs)
        view._is_coroutine = asyncio.coroutines._is_coroutine
        return view

    async def post(self, request):
        """Async post"""
        status = 200
        order_id = int(request.POST.get('order_id', 0))
        platform = request.POST.get('platform', "")

        if order_id and platform:
            data = await self.push_data(order_id, platform)
            message = data
        else:
            status = 400
            message = "Invalid Data"

        return JsonResponse({'status': status, 'message': message})

    @sync_to_async
    def push_data(self, order_id, platform):
        hp_ids = list(HasProduct.objects.filter(order_id=order_id).values_list('id', flat=True))
        Helpers.call_status_api(order_id, hp_ids, status=platform)
        return "Request has been queued for processing"

