@staticmethod
def call_status_api(order_id, line_item_ids, status, is_hyperlocal=False):
    """Notify the sync-repo service of a PACK/SHIP/DELIVER status change.

    Hyperlocal (express) line items post to /order/status; store orders post to
    /store-order/status. For store orders, the sync-repo service chains forward
    through the remaining statuses on its own (e.g. a PACK call there also
    triggers SHIP and DELIVER), so this only sends one request.
    """
    if not BACKEND_SYNC_API_BASE_URL:
        logger.warning(f'BACKEND_SYNC_API_BASE_URL not configured, skipping status={status} push for order {order_id}')
        return
    path = '/order/status' if is_hyperlocal else '/store-order/status'
    try:
        response = requests.post(
            f"{BACKEND_SYNC_API_BASE_URL}{path}",
            json={
                'orderId': str(order_id),
                'has_product_ids': [str(lid) for lid in line_item_ids],
                'platform': status,
            },
            headers={'Content-Type': 'application/json', 'x-api-key': BACKEND_SYNC_REPO_API_KEY},
            timeout=10,
        )
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        logger.exception(f'[sync-repo] Request failed for order {order_id} status={status} | {e}')

